#!/usr/bin/env bash
# Rebuild the vendored Basic Pitch engine for the file:// tool pages.
#
#   godot/tools/vendor/basicpitch/build.sh [scratch-dir]
#
# Writes, next to this script (all three are classic scripts: no import/export, no fetch at run time):
#   basicpitch_tf.js     IIFE bundle: TensorFlow.js core + converter + WebGL / WASM / CPU backends + Basic
#                        Pitch's inference and note-creation code. Defines window.BasicPitchVendor =
#                        { tf, loadGraphModel, setWasmPaths, BasicPitch, outputToNotesPoly, noteFramesToTime,
#                          addPitchBendsToNoteEvents, versions }.
#   basicpitch_model.js  the Basic Pitch graph model: window.BASIC_PITCH_MODEL = { modelTopology, weightSpecs,
#                        weightData (base64 of the weight shards), format, generatedBy, convertedBy, signature }.
#   basicpitch_wasm.js   tfjs-backend-wasm's SIMD binary as base64: window.BASIC_PITCH_WASM_SIMD.
# The page-facing API (BasicPitchLite.ready / transcribe) is godot/tools/transcribe_notes.js, which loads
# these with <script> on first use.
#
# Pinned versions (change them here, rebuild, rerun `godot/tools/tests/run_tests.sh transcribe`):
#   @spotify/basic-pitch            1.0.1   Apache-2.0  (src/inference.ts, src/toMidi.ts, model/)
#   @tensorflow/tfjs-core           4.22.0  Apache-2.0
#   @tensorflow/tfjs-converter      4.22.0  Apache-2.0
#   @tensorflow/tfjs-backend-webgl  4.22.0  Apache-2.0
#   @tensorflow/tfjs-backend-wasm   4.22.0  Apache-2.0  (the .wasm holds XNNPACK & co — see NOTICE)
#   @tensorflow/tfjs-backend-cpu    4.22.0  Apache-2.0
#   esbuild                         0.25.10 (build only)
# Basic Pitch 1.0.1 declares @tensorflow/tfjs ^3.2.0; it only uses core ops + loadGraphModel, which 4.22.0
# keeps (the transcribe suite checks the notes). Its `@tensorflow/tfjs` import is aliased to core +
# converter, and `@tonejs/midi` (MIDI file writing, unused here) to a stub that throws. Bundled
# transitively: long 4.0.0 (Apache-2.0), seedrandom 3.0.5 (MIT) — see NOTICE.
#
# Needs node + npm with registry access. The scratch dir is left behind for inspection.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
WORK="${1:-$(mktemp -d)}"
mkdir -p "$WORK/src"
cd "$WORK"
echo "scratch: $WORK"

BP=1.0.1; TF=4.22.0; ESB=0.25.10
[ -f package.json ] || npm init -y >/dev/null
npm install --no-audit --no-fund --save-exact \
  "@tensorflow/tfjs-core@$TF" "@tensorflow/tfjs-converter@$TF" "@tensorflow/tfjs-backend-webgl@$TF" \
  "@tensorflow/tfjs-backend-wasm@$TF" "@tensorflow/tfjs-backend-cpu@$TF" "esbuild@$ESB"
rm -rf bp && mkdir bp
npm pack "@spotify/basic-pitch@$BP" --pack-destination bp >/dev/null
tar xzf "bp/spotify-basic-pitch-$BP.tgz" -C bp
PKG="$WORK/bp/package"

cat > src/tfjs_shim.js <<'EOF'
// what basic-pitch's `import * as tf from '@tensorflow/tfjs'` needs: core ops + loadGraphModel
export * from '@tensorflow/tfjs-core';
export { loadGraphModel, GraphModel } from '@tensorflow/tfjs-converter';
EOF
cat > src/midi_stub.js <<'EOF'
// @tonejs/midi is only used by basic-pitch's generateFileData (MIDI file writing), which we never call
export class Midi { constructor() { throw new Error('basicpitch_tf.js: MIDI file writing is not bundled'); } }
EOF
cat > src/entry.js <<EOF
import * as tf from '@tensorflow/tfjs-core';
// basic-pitch calls tensor.slice() / .reshape(): the chained-op methods the full @tensorflow/tfjs registers
import '@tensorflow/tfjs-core/dist/public/chained_ops/register_all_chained_ops';
import '@tensorflow/tfjs-backend-webgl';
import { setWasmPaths } from '@tensorflow/tfjs-backend-wasm';
import '@tensorflow/tfjs-backend-cpu';
import { loadGraphModel } from '@tensorflow/tfjs-converter';
import { BasicPitch } from '$PKG/src/inference.ts';
import { outputToNotesPoly, noteFramesToTime, addPitchBendsToNoteEvents } from '$PKG/src/toMidi.ts';
window.BasicPitchVendor = { tf, loadGraphModel, setWasmPaths, BasicPitch, outputToNotesPoly, noteFramesToTime,
  addPitchBendsToNoteEvents, versions: { basicPitch: '$BP', tfjs: '$TF' } };
EOF

cat > src/header.txt <<EOF
/* basicpitch_tf.js — Spotify Basic Pitch (automatic music transcription) for the file:// tool pages.
 * Generated by godot/tools/vendor/basicpitch/build.sh — do not edit by hand. Loaded by transcribe_notes.js.
 *   @spotify/basic-pitch $BP (src/inference.ts + src/toMidi.ts)  Copyright 2022 Spotify AB, Apache-2.0
 *   @tensorflow/tfjs-core / -converter / -backend-webgl / -backend-wasm / -backend-cpu $TF
 *     Copyright Google LLC, Apache-2.0
 *   long 4.0.0 (Apache-2.0), seedrandom 3.0.5 (MIT, Copyright 2019 David Bau)
 * Licence texts: LICENSE (Apache-2.0) and NOTICE in this folder. Defines window.BasicPitchVendor.
 */
EOF

npx esbuild src/entry.js --bundle --format=iife --platform=browser --target=es2019 --minify \
  --legal-comments=none --log-level=warning \
  --alias:@tensorflow/tfjs=./src/tfjs_shim.js --alias:@tonejs/midi=./src/midi_stub.js \
  --define:process.env.NODE_ENV='"production"' \
  --banner:js="$(cat src/header.txt)" \
  --metafile=meta.json --outfile="$HERE/basicpitch_tf.js"

node - "$PKG" "$HERE" "$BP" "$TF" "$WORK/node_modules/@tensorflow/tfjs-backend-wasm/dist/tfjs-backend-wasm-simd.wasm" <<'EOF'
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const [pkg, here, bp, tf, wasmPath] = process.argv.slice(2);
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
// the model: model.json inline, the weight shards concatenated (in manifest order) as base64
const json = JSON.parse(fs.readFileSync(path.join(pkg, 'model/model.json'), 'utf8'));
const bins = [], specs = [];
for (const g of json.weightsManifest) { for (const p of g.paths) bins.push(fs.readFileSync(path.join(pkg, 'model', p))); specs.push(...g.weights); }
const data = Buffer.concat(bins);
const model = { format: json.format, generatedBy: json.generatedBy, convertedBy: json.convertedBy,
  signature: json.signature, modelTopology: json.modelTopology, weightSpecs: specs };
const msrc = [
  '/* basicpitch_model.js — the Basic Pitch graph model (@spotify/basic-pitch ' + bp + ' model/) as a classic script.',
  ' * Generated by godot/tools/vendor/basicpitch/build.sh — do not edit by hand. Copyright 2022 Spotify AB, Apache-2.0.',
  ' * model.json topology + weight specs inline; the weight shards concatenated, base64 in weightData.',
  ' *   weights sha256 ' + sha(data) + ' (' + data.length + ' bytes)',
  ' * transcribe_notes.js hands this to tf.io.fromMemory — never fetch(): Chrome blocks it on file://.',
  ' */',
  'window.BASIC_PITCH_MODEL = ' + JSON.stringify(model) + ';',
  'window.BASIC_PITCH_MODEL.weightData = "' + data.toString('base64') + '";',
  '',
].join('\n');
fs.writeFileSync(path.join(here, 'basicpitch_model.js'), msrc);
// the WASM backend's SIMD binary (single-threaded: file:// pages are never cross-origin isolated)
const wasm = fs.readFileSync(wasmPath);
const wsrc = [
  '/* basicpitch_wasm.js — @tensorflow/tfjs-backend-wasm ' + tf + ' dist/tfjs-backend-wasm-simd.wasm as base64.',
  ' * Generated by godot/tools/vendor/basicpitch/build.sh — do not edit by hand. Apache-2.0 (tfjs); the binary',
  ' * contains XNNPACK, pthreadpool, cpuinfo, FP16, FXdiv and the Emscripten runtime — see NOTICE.',
  ' *   sha256 ' + sha(wasm) + ' (' + wasm.length + ' bytes)',
  ' * transcribe_notes.js hands it to setWasmPaths as a data: URL — no .wasm file is ever requested.',
  ' */',
  'window.BASIC_PITCH_WASM_SIMD = "' + wasm.toString('base64') + '";',
  '',
].join('\n');
fs.writeFileSync(path.join(here, 'basicpitch_wasm.js'), wsrc);
console.log('model: ' + specs.length + ' weights, ' + data.length + ' bytes; wasm: ' + wasm.length + ' bytes');
EOF

ls -la "$HERE"/*.js
node -e "const m=require('./meta.json');const o=Object.values(m.outputs)[0];const by={};for(const[k,v]of Object.entries(o.inputs)){const p=k.match(/node_modules\/(@[^/]+\/[^/]+|[^/]+)/);const n=p?p[1]:'@spotify/basic-pitch';by[n]=(by[n]||0)+v.bytesInOutput}console.log('bundle bytes by package:',by)"
